// vol-two-clicks v1
// Cambia la herramienta Volumen de drag&drop a DOS CLICS:
//   1er clic izq: fija esquina A (primer vertice de la base)
//   2do clic izq: fija esquina B (segundo vertice de la base)
//   3er clic izq: fija la altura (igual que antes)
//   clic dcho: planta el volumen (igual que antes)
//
// La preview en vivo de la base sigue funcionando porque el render
// (boxStep===1) ya lee la posicion apuntada en cada frame.
//
// API:
//   game.volTwoClicks.on()      activa
//   game.volTwoClicks.off()     restaura drag&drop original
//   game.volTwoClicks.estado()  info
//
(() => {
'use strict';

const origBoxClick = window.mcBoxClick;
const origBoxMouseUp = window.mcBoxMouseUp;
if(typeof origBoxClick !== 'function') throw new Error('vol-two-clicks: no encuentro mcBoxClick');
if(typeof origBoxMouseUp !== 'function') throw new Error('vol-two-clicks: no encuentro mcBoxMouseUp');

let activo = false;

function patchedBoxClick(){
  const near = mcRaycast(mcReach(), true);
  // Paso 0: primer clic fija esquina A
  if(!mc.boxStep || mc.boxStep === 0){
    if(!near) return;
    const n = near.normal;
    const px = near.cell[0] + n[0], py = near.cell[1] + n[1], pz = near.cell[2] + n[2];
    mc.boxA = [px, py, pz];
    mc.boxStep = 1;
    toast('Esquina A fijada. Clic izq en la esquina opuesta para fijar la base');
    return;
  }
  // Paso 1: segundo clic fija esquina B (base) - ANTES era mouseup/drag
  if(mc.boxStep === 1){
    const a = mc.boxA;
    if(!a){ mc.boxStep = 0; return; }
    let bx = a[0], bz = a[2];
    if(near){ bx = near.cell[0] + near.normal[0]; bz = near.cell[2] + near.normal[2]; }
    mc.boxB = [bx, a[1], bz];
    mc.boxPitch0 = mc.pitch;
    mc.boxStep = 2;
    const w = Math.abs(bx - a[0]) + 1, d = Math.abs(bz - a[2]) + 1;
    toast('Base fijada (' + w + 'x' + d + '). Mueve la mirada arriba/abajo y clic izq para altura');
    return;
  }
  // Pasos 2 y 3: sin cambios, delegamos al original
  // (pero como el original tambien maneja pasos 0 y 1, llamamos directamente
  //  la logica de pasos 2+ que esta en el original)
  return origBoxClick.call(this);
}

function patchedBoxMouseUp(){
  // No-op: ya no necesitamos el mouseup para fijar la base
  // (se hace con el segundo clic)
}

function instalar(){
  window.mcBoxClick = patchedBoxClick;
  window.mcBoxMouseUp = patchedBoxMouseUp;
  activo = true;
}

function desinstalar(){
  window.mcBoxClick = origBoxClick;
  window.mcBoxMouseUp = origBoxMouseUp;
  activo = false;
}

function estado(){
  const s = 'vol-two-clicks: ' + (activo ? 'ACTIVO (2 clics)' : 'inactivo (drag&drop original)');
  console.log(s);
  return s;
}

const API = {
  on(){ if(!activo) instalar(); return 'vol-two-clicks activado'; },
  off(){ if(activo) desinstalar(); return 'vol-two-clicks desactivado'; },
  estado
};
game.volTwoClicks = API;
API.on();
})();
